#include "room_test_resources.hpp"
#include "room_core.hpp"
#include "room_json.hpp"
#include <fstream>
#include <iostream>
namespace wot::room {
struct LobbyProbe {
 static Value run(const Value&input,const Value&resources){Value config=object();config.object["schema"]=integer(1);Core core(config,resources,[](auto,auto,auto){return true;},[](auto,auto){},[](auto,auto){},[](const Value&v)->std::optional<Value>{return v;});auto&state=core.state_;state.phase="battle";state.round_id=1;state.authority_epoch=1;state.server_tick=300;state.server_time_ms=10000;state.map_name="04_himmelsdorf";state.monotonic_seconds=100.;core.roster_=input.get("roster");core.clock_us_=1000000;for(const auto&r:rows(input.get("players")))state.players[intField(r,"player_id",intField(r,"id"))]=r;for(const auto&[k,v]:input.get("config").object)state.config.object[k]=v;Value results=array();for(const auto&message:rows(input.get("messages"))){Value result=object();try{core.worker(objectView(freeze(message)));result.object["accepted"]=boolean(true);}catch(const std::exception&e){result.object["accepted"]=boolean(false);result.object["error"]=text(e.what());}results.array.push_back(std::move(result));}Value out=object();out.object["results"]=std::move(results);out.object["manifest"]=state.bot_manifest;out.object["bots"]=array();for(const auto&[id,row]:state.bots){(void)id;if(row.reference)throw std::logic_error("Canonical Bot state aliases an immutable resource template");Value clean=row;std::vector<std::string>remove;for(const auto&kv:clean.object)if(kv.first=="vehicle_tier"||kv.first=="vehicle_class"||kv.first=="critical_profile"||kv.first=="terminal_critical"||kv.first.find("room_")==0)remove.push_back(kv.first);for(const auto&key:remove)clean.object.erase(key);out.object["bots"].array.push_back(std::move(clean));}out.object["snapshot"]=core.snapshot();out.object["events"]=array();out.object["events"].array=state.events;out.object["bot_state_revision"]=integer(state.bot_state_revision);out.object["bot_state_time_us"]=integer(state.bot_state_time_us);return out;}
};
}
int main(int argc,char**argv){if(argc!=2)return 2;std::ifstream file(argv[1]);const std::string content((std::istreambuf_iterator<char>(file)),{});const auto resources=wot::room::testResources(wot::room::parseJson(content));std::string line;while(std::getline(std::cin,line)){try{std::cout<<wot::room::writeJson(wot::room::LobbyProbe::run(wot::room::parseJson(line),resources))<<'\n';}catch(const std::exception&e){auto error=wot::room::object();error.object["error"]=wot::room::text(e.what());std::cout<<wot::room::writeJson(error)<<'\n';}}}
